from pathlib import Path
import os,json,hashlib,traceback
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parent;Q=Path(os.environ.get('RF314_QA',str(R/'qa/file')));Q.mkdir(parents=True,exist_ok=True)
M=json.loads((R/'BUILD_MANIFEST.json').read_text());URL=os.environ.get('RF314_URL',(R/'preview.html').as_uri())
report={'version':'REALITY-HC-S3.14','sourceCommit':M['sourceCommit'],'url':URL,'passed':False,'checks':[],'pageErrors':[],'consoleErrors':[],'failedRequests':[],'physicalDeviceTested':False,'fitCertified':False};requests=[]
def save():(Q/'BROWSER.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
def check(name,ok,detail=None):
 if not ok:raise AssertionError(name+': '+str(detail))
 report['checks'].append({'name':name,'passed':True,'detail':detail});print('PASS',name,flush=True);save()
def shot(page,name):
 p=Q/(name+'.png');page.screenshot(path=str(p),timeout=60000);report.setdefault('screenshots',[]).append({'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
with sync_playwright() as pw:
 browser=pw.chromium.launch(headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
 context=browser.new_context(viewport={'width':1440,'height':1100},device_scale_factor=1,accept_downloads=True)
 page=context.new_page();page.set_default_timeout(60000)
 page.on('pageerror',lambda e:report['pageErrors'].append(str(e)));page.on('console',lambda e:report['consoleErrors'].append(e.text) if e.type=='error' else None)
 page.on('request',lambda r:requests.append(r.url) if r.url.startswith(('http:','https:')) else None);page.on('requestfailed',lambda r:report['failedRequests'].append({'url':r.url,'reason':r.failure}))
 state=lambda:page.evaluate('__RF314__.report()')
 try:
  page.goto(URL,wait_until='domcontentloaded',timeout=120000);page.wait_for_function('!!window.__RF314__')
  check('exact source build',state()['sourceCommit']==M['sourceCommit'])
  check('embedded evidence hash verified',state()['payloadSHA256']==M['payloadSHA256'])
  check('default is actual102 reachability and shape result',state()['ci']==2 and state()['variant']=='reach_shape' and len(state()['selected']['s']['nodes'])==24)
  check('default prepared scope individually reachable not jointly certified',state()['selected']['v']['preflight']['status']=='INDIVIDUAL_FIRST_ROWS_REACHABLE' and not state()['selected']['v']['preflight']['jointFeasibilityProved'])
  check('added endpoints are visible','447' in page.locator('#reach').inner_text() and '448' in page.locator('#reach').inner_text() and '50' in page.locator('#reach').inner_text())
  check('source writes and motion never claimed',not any(state()[k] for k in ['sourceWritten','fullMotionExecuted','fitCertified','live']))
  check('real failed result is clearly labelled','未写回' in page.locator('#result').inner_text() and 'HOLD' in page.locator('#status').inner_text())
  check('three actual frozen fixtures offered',page.locator('#case option').count()==3)
  for variant in ['reference','shape','reach_shape']:
   page.locator('#variant').select_option(variant)
   check(variant+' condition really changes selected evidence',state()['variant']==variant and state()['selected']['v']['variant']==variant)
   check(variant+' keeps rejection not source mutation',not state()['selected']['v']['independentAccepted'] and not state()['selected']['v']['sourceWritten'])
  page.locator('#variant').select_option('reach_shape')
  for seed in ['0','1','2']:
   page.locator('#seed').select_option(seed);check('seed'+seed+' uses actual trial',state()['seed']==int(seed) and len(state()['selected']['s']['iterations'])>0)
  page.locator('#seed').select_option('0');canvas=page.locator('#canvas');before=canvas.screenshot();camera=state()['camera']
  page.locator('#trial').click();after=canvas.screenshot()
  check('rejected trial changes real geometry pixels',hashlib.sha256(before).hexdigest()!=hashlib.sha256(after).hexdigest())
  check('before and trial share camera',state()['camera']==camera)
  check('trial cannot be mistaken for adopted repair','未写回' in page.locator('#view-label').inner_text() and '不是修复结果' in page.locator('#view-label').inner_text())
  shot(page,'01-rejected-shape-trial')
  page.locator('#before').click();check('restored exact input pixels',hashlib.sha256(before).hexdigest()==hashlib.sha256(canvas.screenshot()).hexdigest())
  check('contact-only certificate does not include shape',not state()['certificate']['includesLinearizedShape'] and len(state()['certificate']['rows'])==4)
  page.locator('#verify').click();check('browser exact rational recomputation passes',state()['verified']['positive'] and state()['verified']['lowerBoundM']>.0024 and not state()['verified']['nonlinearInfeasibilityProved'])
  check('linear conclusion not global nonlinear impossibility','不代表全局非线性无解' in page.locator('#certificate-result').inner_text())
  page.locator('#include-shape').check();check('changed model invalidates old verification',state()['verified'] is None and state()['certificate']['includesLinearizedShape'])
  page.locator('#verify').click();check('contact plus shape proof also recomputed',state()['verified']['positive'] and state()['verified']['lowerBoundM']>.0027)
  for i in ['0','1']:
   page.locator('#case').select_option(i);check('step30 fixture'+i+' correctly selected',state()['ci']==int(i) and state()['selected']['item']['step']==30 and len(state()['selected']['s']['nodes'])==13)
   page.locator('#include-shape').uncheck();page.locator('#verify').click();check('step30 fixture'+i+' proof recomputes',state()['verified']['positive'] and .0011<state()['verified']['lowerBoundM']<.0012)
  page.locator('#reset').click();check('reset returns original frozen default',state()['ci']==2 and state()['variant']=='reach_shape' and state()['seed']==0 and state()['phase']=='before' and state()['verified'] is None)
  shot(page,'02-default102')
  box=canvas.bounding_box();check('real WebGL canvas visible',box['width']>300 and box['height']>250 and state()['draws']>0)
  pixels=canvas.screenshot();cam=state()['camera'];page.mouse.move(box['x']+box['width']*.5,box['y']+box['height']*.5);page.mouse.down();page.mouse.move(box['x']+box['width']*.65,box['y']+box['height']*.6,steps=8);page.mouse.up()
  check('orbit changes camera and actual pixels',state()['camera']!=cam and hashlib.sha256(pixels).hexdigest()!=hashlib.sha256(canvas.screenshot()).hexdigest())
  old=state()['camera']['zoom'];page.mouse.wheel(0,-180);page.wait_for_timeout(100);check('actual wheel zoom',state()['camera']['zoom']!=old)
  pixels=canvas.screenshot();page.locator('#surface').uncheck();check('body visibility changes pixels',hashlib.sha256(pixels).hexdigest()!=hashlib.sha256(canvas.screenshot()).hexdigest());page.locator('#surface').check()
  page.locator('#camera-reset').click();check('camera resets',state()['camera']=={'yaw':-.5,'pitch':.2,'zoom':1})
  page.locator('#verify').click()
  with page.expect_download() as ev:page.locator('#export').click()
  export=Q/'EXPORTED_REVIEW.json';ev.value.save_as(export);x=json.loads(export.read_text())
  check('export contains true conditions and no fit authority',x['schema']=='kaopu/contact-shape-review-export@1' and len(x['data']['cases'])==3 and not x['fitCertified'] and not x['sourceWritten'] and not x['fullMotionExecuted'])
  check('export retains independently checked rational evidence',x['verified']['positive'] and len(x['data']['certificates'])==6)
  check('no hidden heavy native runtime',page.locator('iframe').count()==0)
  page.set_viewport_size({'width':390,'height':844});page.evaluate('scrollTo(0,0)');page.wait_for_timeout(100);check('390px fits without horizontal overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth+2'));shot(page,'03-mobile')
  if URL.startswith('file:'):check('standalone has no HTTP dependencies',not requests,requests)
  check('zero page errors',not report['pageErrors'],report['pageErrors']);check('zero console errors',not report['consoleErrors'],report['consoleErrors']);check('zero failed requests',not report['failedRequests'],report['failedRequests'])
  report['passed']=True;report['fileVerified']=URL.startswith('file:');report['publicVerified']=URL.startswith('https:')
 except Exception as e:
  report['failure']=str(e);report['trace']=traceback.format_exc();print(report['trace'],flush=True)
  try:report['lastState']=state();shot(page,'FAILURE')
  except Exception as e2:report['captureFailure']=str(e2)
 finally:save();context.close();browser.close()
if not report['passed']:raise SystemExit(1)
